using Microsoft.Data.SqlClient;

namespace Acme.Orders.Data;

public sealed class OrderRepository(string connectionString)
{
    public List<Order> FindByCustomer(string customerCode, string status)
    {
        using var connection = new SqlConnection(connectionString);
        connection.Open();
        using var command = connection.CreateCommand();
        command.CommandText =
            "SELECT Id, CustomerCode, Status, Total FROM Orders " +
            "WHERE CustomerCode = '" + customerCode + "' AND Status = '" + status + "'";
        using var reader = command.ExecuteReader();
        var orders = new List<Order>();
        while (reader.Read())
        {
            orders.Add(new Order(
                reader.GetInt32(0), reader.GetString(1), reader.GetString(2), reader.GetDecimal(3)));
        }
        return orders;
    }
}

public sealed record Order(int Id, string CustomerCode, string Status, decimal Total);

