using Dapper;
using Microsoft.Data.SqlClient;

public async Task<IReadOnlyList<Order>> FindByCustomerAsync(
    string customerCode, string status, CancellationToken ct)
{
    const string sql = """
        SELECT Id, CustomerCode, Status, Total
        FROM Orders
        WHERE CustomerCode = @customerCode AND Status = @status
        """;

    await using var connection = new SqlConnection(connectionString);
    var orders = await connection.QueryAsync<Order>(
        new CommandDefinition(sql, new { customerCode, status }, cancellationToken: ct));
    return orders.AsList();
}

public async Task<IReadOnlyList<Order>> FindByCustomerAsync(
    string customerCode, IReadOnlyCollection<string> statuses, CancellationToken ct)
{
    const string sql = """
        SELECT Id, CustomerCode, Status, Total
        FROM Orders
        WHERE CustomerCode = @customerCode AND Status IN @statuses
        """;

    await using var connection = new SqlConnection(connectionString);
    var orders = await connection.QueryAsync<Order>(
        new CommandDefinition(sql, new { customerCode, statuses }, cancellationToken: ct));
    return orders.AsList();
}
